cypress_script:
describe('Product Search Functionality', () => {
    it('should display filtered products when a valid search term is entered', () => {
        cy.visit('https://automationexercise.com/products');
        cy.get('#search_product').type('Tshirt');
        cy.get('#submit_search').click();
        cy.url().should('include', 'search=Tshirt');
        cy.get('.google-anno').should('be.visible');
    });

    it('should display no products when an invalid search term is entered', () => {
        cy.visit('https://automationexercise.com/products');
        cy.get('#search_product').type('NonExistentProduct');
        cy.get('#submit_search').click();
        cy.url().should('include', 'search=NonExistentProduct');
        cy.get('.google-anno').should('not.exist');
    });
});

playwright_script:
test.describe('Product Search Functionality', () => {
    test('should display filtered products when a valid search term is entered', async ({ page }) => {
        await page.goto('https://automationexercise.com/products');
        await page.fill('#search_product', 'Tshirt');
        await page.click('#submit_search');
        await page.waitForURL(/.*search=Tshirt/);
        const productVisible = await page.isVisible('.google-anno');
        expect(productVisible).toBe(true);
    });

    test('should display no products when an invalid search term is entered', async ({ page }) => {
        await page.goto('https://automationexercise.com/products');
        await page.fill('#search_product', 'NonExistentProduct');
        await page.click('#submit_search');
        await page.waitForURL(/.*search=NonExistentProduct/);
        const productVisible = await page.isVisible('.google-anno');
        expect(productVisible).toBe(false);
    });
});
